    #[test]
    fn later_thread_exit_full_medium_force_collects_to_a_client_free_only_mapped_process_route() {
        thread::spawn(|| {
            let config = memory_config();
            let storage = MainStaticAttachmentStorage::test_static_owner();
            let subprocess = MainSubprocess::test_static_owner();
            let metadata = MetaAllocator::test_static_owner();
            let (page_map, process_arena) = paired_process_owner(config, subprocess);
            let pair = ProcessPageArenaLease::join(page_map, process_arena)
                .expect("the selected process owners match");
            let main = unsafe {
                MainStaticTheapAttachment::begin_with_test_storage(storage, subprocess)
            }
            .expect("ticket zero attaches the source-static main images");
            let main_heap = main.shared_main_heap_lease().unwrap();

            thread::scope(|scope| {
                let worker = scope.spawn(move || {
                    let arena = process_arena
                        .arena()
                        .expect("the paired arena remains published through the route");
                    let mut owner = match unsafe {
                        MainHeapThreadAttachment::begin_with_test_metadata(main_heap, metadata, config)
                    } {
                        Ok(owner) => owner,
                        Err(MainHeapThreadAttachmentBeginError::Rejected(error)) => {
                            panic!("later source thread attachment rejected: {error:?}")
                        }
                        Err(MainHeapThreadAttachmentBeginError::Retained { error, .. }) => {
                            panic!("later source thread attachment retained: {error:?}")
                        }
                    };
                    let mut allocator = MainHeapThreadProcessPageAllocator::begin(&mut owner, pair)
                        .expect("the matched process pair admits the force-collection fixture");
                    let request = SMALL_MAX_OBJ_SIZE + 1;
                    let first = allocator
                        .allocate(request, false)
                        .expect("the fixture creates one medium regular page");
                    let page = NonNull::new(unsafe { allocator.test_page_for_block(first) })
                        .expect("the full medium page stays PageMap-published");
                    let capacity = unsafe { page.as_ref().reserved() as usize };
                    assert!(
                        capacity >= 16,
                        "the chosen medium geometry exposes a distinct full queue state"
                    );
                    let mut blocks = std::vec::Vec::with_capacity(capacity);
                    blocks.push(first);
                    while blocks.len() < capacity {
                        let block = allocator
                            .allocate(request, false)
                            .expect("the fixture fills exactly one medium page");
                        assert_eq!(
                            unsafe { allocator.test_page_for_block(block) },
                            page.as_ptr(),
                            "the fixture does not allocate a second medium page"
                        );
                        blocks.push(block);
                    }
                    let page_ref = unsafe { page.as_ref() };
                    assert_eq!(
                        crate::size_class::page_kind_for_block_size(page_ref.block_size()),
                        Some(crate::types::PageKind::Medium),
                        "the source transition starts from one medium page"
                    );
                    assert_eq!(page_ref.used(), capacity);
                    assert!(
                        crate::types::page_queue::page_is_in_full(page_ref),
                        "the source transition begins in BIN_FULL"
                    );
                    let arena_memory = page_ref
                        .memid()
                        .arena_memory()
                        .expect("the full medium page belongs to the paired arena");
                    let slice = arena_memory.slice_index as usize;
                    let slice_count = arena_memory.slice_count as usize;
                    assert_eq!(
                        slice_count,
                        crate::page::regular_page_slice_count(crate::types::PageKind::Medium)
                            .expect("medium source spans have fixed geometry"),
                        "the process route preserves the full medium PageMap span"
                    );
                    let slice_start = arena
                        .slice_start(slice)
                        .expect("the source medium slice remains addressable");

                    // Preserve the source remote state until `MI_ABANDON`
                    // force-collection. The first block is no longer a
                    // client alias after this producer publishes; `blocks[1]`
                    // remains the exact live witness supplied to the route.
                    let producer = unsafe { allocator.begin_remote_free(blocks[0]) }
                        .expect("the full medium page admits one scoped remote producer");
                    thread::scope(|scope| {
                        let publisher = scope.spawn(move || producer.publish());
                        match publisher.join().expect("the remote producer publishes") {
                            Ok(()) => {}
                            Err((producer, error)) => {
                                let _ = producer.cancel();
                                panic!("the remote client publishes before owner exit: {error:?}");
                            }
                        }
                    });
                    assert_eq!(unsafe { page.as_ref().used() }, capacity);
                    assert_eq!(
                        allocator.test_queue_count(crate::config::BIN_FULL),
                        Some(1)
                    );

                    let drain = allocator.begin_thread_exit_drain().unwrap_or_else(|failure| {
                        let MainHeapThreadProcessPageExitDrainFailure::Retained { allocator, error } = failure;
                        core::mem::forget(allocator);
                        panic!("thread exit enters its post-fast-slot drain: {error:?}");
                    });
                    let route = match unsafe {
                        drain.abandon_full_medium_after_force_collect_to_mapped_process_route(
                            blocks[1],
                        )
                    } {
                        Ok(route) => route,
                        Err(_) => panic!(
                            "a full medium page that force-collection makes nonfull enters the mapped process route"
                        ),
                    };

                    assert_eq!(
                        owner.finish_after_page_drain(),
                        Err(MainHeapThreadAttachmentError::TornDown),
                        "the mapped route tears down the old Theap/TLD before client frees"
                    );
                    assert_eq!(unsafe { page.as_ref().used() }, capacity - 1);
                    assert!(
                        !crate::types::page_queue::page_is_in_full(unsafe { page.as_ref() }),
                        "queue removal clears the source full flag after force collection"
                    );
                    assert_eq!(route.test_abandoned_count(), Some(1));
                    for offset in 0..slice_count {
                        let address = unsafe {
                            slice_start.add(offset * crate::config::ARENA_SLICE_SIZE)
                        };
                        assert_eq!(
                            unsafe { page_map.page_map().unwrap().checked_lookup(address) },
                            page.as_ptr(),
                            "mapped abandonment retains every medium PageMap slice"
                        );
                    }

                    // The final medium/nonfull geometry does not erase the
                    // source full origin. It must reject before a fresh
                    // attachment can claim the bitmap member or create a
                    // target page engine, leaving this route as the sole
                    // client-free owner.
                    let mut target = match unsafe {
                        MainHeapThreadAttachment::begin_with_test_metadata(
                            main_heap,
                            metadata,
                            config,
                        )
                    } {
                        Ok(owner) => owner,
                        Err(MainHeapThreadAttachmentBeginError::Rejected(error)) => {
                            panic!("fresh full-origin target attachment rejected: {error:?}")
                        }
                        Err(MainHeapThreadAttachmentBeginError::Retained { error, .. }) => {
                            panic!("fresh full-origin target attachment retained: {error:?}")
                        }
                    };
                    let route = match route.adopt_into_later_main(&mut target, pair) {
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularAdoptFailure::Rejected {
                                route,
                                error,
                            },
                        ) => {
                            assert_eq!(
                                error,
                                MainHeapThreadProcessPageExitMappedRegularAdoptError::SourceNotInitiallyNonfullAdoptable,
                                "the force-collected full origin rejects before target page-engine transfer"
                            );
                            route
                        }
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularAdoptFailure::Retained {
                                adoption,
                                error,
                            },
                        ) => {
                            core::mem::forget(adoption);
                            panic!(
                                "the force-collected full origin cannot claim or mutate a target: {error:?}"
                            );
                        }
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularAdoptFailure::Reabandoned {
                                adoption,
                                error,
                            },
                        ) => {
                            core::mem::forget(adoption);
                            panic!(
                                "the force-collected full origin cannot enter the target commit/reabandon branch: {error:?}"
                            );
                        }
                        Ok(allocator) => {
                            core::mem::forget(allocator);
                            panic!(
                                "the force-collected full origin cannot become a normal allocation owner"
                            );
                        }
                    };
                    assert_eq!(
                        target.finish_after_user_destructors(),
                        Ok(()),
                        "the pre-transfer full-origin refusal leaves the fresh target attachment empty"
                    );
                    assert_eq!(
                        unsafe { page_map.page_map().unwrap().checked_lookup(blocks[1].as_ptr()) },
                        page.as_ptr(),
                        "the full-origin refusal leaves its exact PageMap entry published"
                    );
                    assert_eq!(
                        unsafe { arena.pages() }.unwrap().is_clear_range(slice, 1),
                        Some(false),
                        "the full-origin refusal cannot claim or clear the static-main arena bitmap member"
                    );
                    assert_eq!(route.test_abandoned_count(), Some(1));

                    let mut route = route;

                    for block in blocks.iter().copied().skip(1).take(capacity - 2) {
                        route = match unsafe { route.remote_free_after_thread_exit(block) } {
                            Ok(MainHeapThreadProcessPageExitMappedRegularFreeResult::StillLive(route)) => {
                                route
                            }
                            Ok(MainHeapThreadProcessPageExitMappedRegularFreeResult::Released) => {
                                panic!("a nonfinal mapped client free cannot release the medium page")
                            }
                            Err(_) => panic!("a mapped medium client free remains in the process route"),
                        };
                        assert_eq!(route.test_abandoned_count(), Some(1));
                    }
                    match unsafe {
                        route.remote_free_after_thread_exit(
                            *blocks.last().expect("the full medium page has a last live block"),
                        )
                    } {
                        Ok(MainHeapThreadProcessPageExitMappedRegularFreeResult::Released) => {}
                        Ok(MainHeapThreadProcessPageExitMappedRegularFreeResult::StillLive(route)) => {
                            core::mem::forget(route);
                            panic!("the final mapped client free releases the medium page")
                        }
                        Err(_) => panic!("the final mapped client free releases the medium page"),
                    }
                    for offset in 0..slice_count {
                        let address = unsafe {
                            slice_start.add(offset * crate::config::ARENA_SLICE_SIZE)
                        };
                        assert!(
                            unsafe { page_map.page_map().unwrap().checked_lookup(address) }.is_null(),
                            "the terminal release unregisters every medium PageMap slice"
                        );
                    }
                    assert_eq!(
                        unsafe { arena.pages() }.unwrap().is_clear_range(slice, 1),
                        Some(true),
                        "the final mapped release clears the ordinary main-arena bit"
                    );
                    assert_eq!(
                        page_map.begin_page_lifecycle().unwrap().finish(),
                        Ok(()),
                        "the completed route reopens an empty process map"
                    );
                });
                worker
                    .join()
                    .expect("the force-collected medium route remains current-thread local");
            });
            core::mem::forget(main);
        })
        .join()
        .expect("full-medium force-collection process route fixture remains current-thread local");
    }

    #[test]
    fn later_thread_exit_full_medium_force_collect_route_rejects_a_regular_medium_before_mutation() {
        thread::spawn(|| {
            let config = memory_config();
            let storage = MainStaticAttachmentStorage::test_static_owner();
            let subprocess = MainSubprocess::test_static_owner();
            let metadata = MetaAllocator::test_static_owner();
            let (page_map, process_arena) = paired_process_owner(config, subprocess);
            let pair = ProcessPageArenaLease::join(page_map, process_arena)
                .expect("the selected process owners match");
            let main = unsafe {
                MainStaticTheapAttachment::begin_with_test_storage(storage, subprocess)
            }
            .expect("ticket zero attaches the source-static main images");
            let main_heap = main.shared_main_heap_lease().unwrap();

            thread::scope(|scope| {
                let worker = scope.spawn(move || {
                    let mut owner = match unsafe {
                        MainHeapThreadAttachment::begin_with_test_metadata(main_heap, metadata, config)
                    } {
                        Ok(owner) => owner,
                        Err(MainHeapThreadAttachmentBeginError::Rejected(error)) => {
                            panic!("later source thread attachment rejected: {error:?}")
                        }
                        Err(MainHeapThreadAttachmentBeginError::Retained { error, .. }) => {
                            panic!("later source thread attachment retained: {error:?}")
                        }
                    };
                    let mut allocator = MainHeapThreadProcessPageAllocator::begin(&mut owner, pair)
                        .expect("the matched process pair admits the preflight fixture");
                    let block = allocator
                        .allocate(SMALL_MAX_OBJ_SIZE + 1, false)
                        .expect("the fixture creates one nonfull medium page");
                    let page = NonNull::new(unsafe { allocator.test_page_for_block(block) })
                        .expect("the regular medium page stays PageMap-published");
                    let bin = crate::size_class::bin(unsafe { page.as_ref().block_size() })
                        .expect("the regular medium page has one source bin");
                    assert_eq!(unsafe { page.as_ref().used() }, 1);
                    assert!(
                        !crate::types::page_queue::page_is_in_full(unsafe { page.as_ref() }),
                        "the refusal fixture starts in its ordinary medium queue"
                    );

                    let drain = allocator.begin_thread_exit_drain().unwrap_or_else(|failure| {
                        let MainHeapThreadProcessPageExitDrainFailure::Retained { allocator, error } = failure;
                        core::mem::forget(allocator);
                        panic!("thread exit enters its post-fast-slot drain: {error:?}");
                    });
                    let drain = match unsafe {
                        drain.abandon_full_medium_after_force_collect_to_mapped_process_route(block)
                    } {
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::Rejected {
                                drain,
                                error,
                            },
                        ) => {
                            assert_eq!(
                                error,
                                ThreadExitMappedRegularPostExitAbandonError::NotFullMedium,
                                "a regular medium page cannot enter the full-to-nonfull source branch"
                            );
                            drain
                        }
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::RetainedDrain {
                                drain,
                                error,
                            },
                        ) => {
                            core::mem::forget(drain);
                            panic!("the full-medium shape rejects before source collection: {error:?}");
                        }
                        Err(MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::Teardown {
                            terminal,
                            ..
                        }) => {
                            core::mem::forget(terminal);
                            panic!("the full-medium shape rejects before Theap/TLD teardown");
                        }
                        Err(MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::PageMap {
                            parts,
                            error,
                        }) => {
                            core::mem::forget(parts);
                            panic!("the full-medium shape rejects before PageMap-route transfer: {error:?}");
                        }
                        Ok(route) => {
                            core::mem::forget(route);
                            panic!("a regular medium page cannot cross into the full-to-nonfull route");
                        }
                    };
                    assert_eq!(
                        unsafe { page_map.page_map().unwrap().checked_lookup(block.as_ptr()) },
                        page.as_ptr(),
                        "the rejected full-medium preflight leaves PageMap publication untouched"
                    );
                    assert_eq!(unsafe { page.as_ref().used() }, 1);
                    assert_eq!(
                        drain.test_queue_count(bin),
                        Some(1),
                        "the rejected preflight leaves the ordinary medium queue member attached"
                    );
                    assert_eq!(drain.test_queue_count(crate::config::BIN_FULL), Some(0));
                    assert!(
                        !crate::types::page_queue::page_is_in_full(unsafe { page.as_ref() }),
                        "the rejected preflight leaves the regular queue's full flag unchanged"
                    );

                    drop(drain);
                    assert_eq!(
                        owner.finish_after_page_drain(),
                        Err(MainHeapThreadAttachmentError::Poisoned),
                        "dropping a rejected drain cannot imitate process-route teardown"
                    );
                    core::mem::forget(owner);
                });
                worker
                    .join()
                    .expect("the full-medium preflight refusal remains current-thread local");
            });
            core::mem::forget(main);
        })
        .join()
        .expect("full-medium preflight refusal fixture remains current-thread local");
    }

    #[test]
    fn later_thread_exit_full_medium_force_collect_route_retains_a_collection_failure() {
        thread::spawn(|| {
            let config = memory_config();
            let storage = MainStaticAttachmentStorage::test_static_owner();
            let subprocess = MainSubprocess::test_static_owner();
            let metadata = MetaAllocator::test_static_owner();
            let (page_map, process_arena) = paired_process_owner(config, subprocess);
            let pair = ProcessPageArenaLease::join(page_map, process_arena)
                .expect("the selected process owners match");
            let main = unsafe {
                MainStaticTheapAttachment::begin_with_test_storage(storage, subprocess)
            }
            .expect("ticket zero attaches the source-static main images");
            let main_heap = main.shared_main_heap_lease().unwrap();

            thread::scope(|scope| {
                let worker = scope.spawn(move || {
                    let mut owner = match unsafe {
                        MainHeapThreadAttachment::begin_with_test_metadata(main_heap, metadata, config)
                    } {
                        Ok(owner) => owner,
                        Err(MainHeapThreadAttachmentBeginError::Rejected(error)) => {
                            panic!("later source thread attachment rejected: {error:?}")
                        }
                        Err(MainHeapThreadAttachmentBeginError::Retained { error, .. }) => {
                            panic!("later source thread attachment retained: {error:?}")
                        }
                    };
                    let mut allocator = MainHeapThreadProcessPageAllocator::begin(&mut owner, pair)
                        .expect("the matched process pair admits the collection-failure fixture");
                    let request = SMALL_MAX_OBJ_SIZE + 1;
                    let first = allocator
                        .allocate(request, false)
                        .expect("the fixture creates one medium regular page");
                    let page = NonNull::new(unsafe { allocator.test_page_for_block(first) })
                        .expect("the full medium page stays PageMap-published");
                    let capacity = unsafe { page.as_ref().reserved() as usize };
                    let mut blocks = std::vec::Vec::with_capacity(capacity);
                    blocks.push(first);
                    while blocks.len() < capacity {
                        let block = allocator
                            .allocate(request, false)
                            .expect("the fixture fills exactly one medium page");
                        assert_eq!(unsafe { allocator.test_page_for_block(block) }, page.as_ptr());
                        blocks.push(block);
                    }
                    assert_eq!(unsafe { page.as_ref().used() }, capacity);
                    assert!(crate::types::page_queue::page_is_in_full(unsafe { page.as_ref() }));

                    let producer = unsafe { allocator.begin_remote_free(blocks[0]) }
                        .expect("the full medium page admits one scoped remote producer");
                    thread::scope(|scope| {
                        let publisher = scope.spawn(move || producer.publish());
                        match publisher.join().expect("the remote producer publishes") {
                            Ok(()) => {}
                            Err((producer, error)) => {
                                let _ = producer.cancel();
                                panic!("the remote client publishes before owner exit: {error:?}");
                            }
                        }
                    });

                    let mut drain = allocator.begin_thread_exit_drain().unwrap_or_else(|failure| {
                        let MainHeapThreadProcessPageExitDrainFailure::Retained { allocator, error } = failure;
                        core::mem::forget(allocator);
                        panic!("thread exit enters its post-fast-slot drain: {error:?}");
                    });
                    drain.engine.inject_page_free_collect_failure_once();
                    let drain = match unsafe {
                        drain.abandon_full_medium_after_force_collect_to_mapped_process_route(
                            blocks[1],
                        )
                    } {
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::RetainedDrain {
                                drain,
                                error,
                            },
                        ) => {
                            assert_eq!(
                                error,
                                ThreadExitMappedRegularPostExitAbandonError::Collection,
                                "force-collection failure retains the only source page owner"
                            );
                            drain
                        }
                        Err(
                            MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::Rejected {
                                drain,
                                error,
                            },
                        ) => {
                            core::mem::forget(drain);
                            panic!("the injected collector fails after source preflight: {error:?}");
                        }
                        Err(MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::Teardown {
                            terminal,
                            ..
                        }) => {
                            core::mem::forget(terminal);
                            panic!("the injected collector fails before Theap/TLD teardown");
                        }
                        Err(MainHeapThreadProcessPageExitMappedRegularRouteBeginFailure::PageMap {
                            parts,
                            error,
                        }) => {
                            core::mem::forget(parts);
                            panic!("the injected collector fails before PageMap-route transfer: {error:?}");
                        }
                        Ok(route) => {
                            core::mem::forget(route);
                            panic!("the injected collection failure cannot create a process route");
                        }
                    };
                    assert!(
                        drain.engine.test_has_collection_poison(),
                        "the drain retains the source collection poison instead of exposing a retry"
                    );
                    assert_eq!(unsafe { page.as_ref().used() }, capacity);
                    assert_eq!(
                        drain.test_queue_count(crate::config::BIN_FULL),
                        Some(1),
                        "the injected failure leaves the full source queue linked"
                    );
                    assert_eq!(
                        unsafe { page_map.page_map().unwrap().checked_lookup(blocks[1].as_ptr()) },
                        page.as_ptr(),
                        "the injected failure leaves PageMap publication intact"
                    );

                    drop(drain);
                    assert_eq!(
                        owner.finish_after_page_drain(),
                        Err(MainHeapThreadAttachmentError::Poisoned),
                        "dropping the retained collector failure cannot imitate process-route teardown"
                    );
                    core::mem::forget(owner);
                });
                worker
                    .join()
                    .expect("the full-medium collection-failure fixture remains current-thread local");
            });
            core::mem::forget(main);
        })
        .join()
        .expect("full-medium collection-failure fixture remains current-thread local");
    }

    #[test]
    fn later_thread_exit_full_large_route_reabandons_after_mostly_used_frees() {
        thread::spawn(|| {
            let config = memory_config();
            let storage = MainStaticAttachmentStorage::test_static_owner();
            let subprocess = MainSubprocess::test_static_owner();
            let metadata = MetaAllocator::test_static_owner();
            let (page_map, process_arena) = paired_process_owner(config, subprocess);
            let pair = ProcessPageArenaLease::join(page_map, process_arena)
                .expect("the selected process owners match");
            let main = unsafe {
                MainStaticTheapAttachment::begin_with_test_storage(storage, subprocess)
            }
            .expect("ticket zero attaches the source-static main images");
            let main_heap = main.shared_main_heap_lease().unwrap();

            thread::scope(|scope| {
                let worker = scope.spawn(move || {
                    let arena = process_arena
                        .arena()
                        .expect("the paired arena remains published through the route");
                    let mut owner = match unsafe {
                        MainHeapThreadAttachment::begin_with_test_metadata(main_heap, metadata, config)
                    } {
                        Ok(owner) => owner,
                        Err(MainHeapThreadAttachmentBeginError::Rejected(error)) => {
                            panic!("later source thread attachment rejected: {error:?}")
                        }
                        Err(MainHeapThreadAttachmentBeginError::Retained { error, .. }) => {
                            panic!("later source thread attachment retained: {error:?}")
                        }
                    };
                    let mut allocator = MainHeapThreadProcessPageAllocator::begin(&mut owner, pair)
                        .expect("the matched process pair admits the full-large fixture");
                    let request = MEDIUM_MAX_OBJ_SIZE + 1;
                    let first = allocator
                        .allocate(request, false)
                        .expect("the fixture creates one large regular page");
                    let page = NonNull::new(unsafe { allocator.test_page_for_block(first) })
                        .expect("the full-large page stays PageMap-published");
                    let capacity = unsafe { page.as_ref().reserved() as usize };
                    assert!(
                        capacity >= 16,
                        "the chosen large geometry exposes the source mostly-used unmapped phase"
                    );
                    let mut blocks = std::vec::Vec::with_capacity(capacity);
                    blocks.push(first);
                    while blocks.len() < capacity {
                        let block = allocator
                            .allocate(request, false)
                            .expect("the fixture fills exactly one large page");
                        assert_eq!(
                            unsafe { allocator.test_page_for_block(block) },
                            page.as_ptr(),
                            "the fixture does not allocate a second large page"
                        );
                        blocks.push(block);
                    }
                    let page_ref = unsafe { page.as_ref() };
                    assert_eq!(
                        crate::size_class::page_kind_for_block_size(page_ref.block_size()),
                        Some(crate::types::PageKind::Large),
                        "the source route begins with a regular large page"
                    );
                    assert_eq!(
                        page_ref.used(),
                        capacity,
                        "the fixture reaches the full large-page boundary"
                    );
                    assert!(
                        crate::types::page_queue::page_is_in_full(page_ref),
                        "a full large page enters the source full queue"
                    );
                    let memory = page_ref.memid();
                    let arena_memory = memory
                        .arena_memory()
                        .expect("the full large page belongs to the paired arena");
                    let slice = arena_memory.slice_index as usize;
                    let slice_count = arena_memory.slice_count as usize;
                    assert_eq!(
                        slice_count,
                        crate::page::regular_page_slice_count(crate::types::PageKind::Large).unwrap(),
                        "the route retains the source large page's complete 64-slice span"
                    );
                    let slice_start = arena
                        .slice_start(slice)
                        .expect("the large arena span has a source start address");

                    let drain = allocator.begin_thread_exit_drain().unwrap_or_else(|failure| {
                        let MainHeapThreadProcessPageExitDrainFailure::Retained { allocator, error } = failure;
                        core::mem::forget(allocator);
                        panic!("thread exit enters its post-fast-slot drain: {error:?}");
                    });
                    let mut route = match unsafe {
                        drain.abandon_full_large_to_process_route(first)
                    } {
                        Ok(route) => route,
                        Err(_) => panic!(
                            "the full large page enters its sequential post-exit process route"
                        ),
                    };

                    assert_eq!(
                        owner.finish_after_page_drain(),
                        Err(MainHeapThreadAttachmentError::TornDown),
                        "the full-large route tears down the old Theap/TLD before client frees"
                    );
                    assert_eq!(
                        unsafe { page_map.page_map().unwrap().checked_lookup(first.as_ptr()) },
                        page.as_ptr(),
                        "the initially unmapped full page remains PageMap-routable after teardown"
                    );
                    assert!(
                        !route.test_is_mapped(),
                        "a full large page begins source-abandoned without a bitmap publication"
                    );
                    assert_eq!(
                        route.test_abandoned_count(),
                        Some(0),
                        "the initial full-page state has no static-main abandoned count"
                    );

                    let unmapped_frees = capacity / 8;
                    assert!(unmapped_frees > 0);
                    let mut index = 0usize;
                    while index < unmapped_frees {
                        route = match unsafe { route.remote_free_after_thread_exit(blocks[index]) } {
                            Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::StillLive(route)) => {
                                route
                            }
                            Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::Released) => {
                                panic!("a mostly-used large page cannot release before all client frees")
                            }
                            Err(_) => panic!("a mostly-used full page remains an unmapped route"),
                        };
                        assert!(
                            !route.test_is_mapped(),
                            "the source keeps a page unmapped through its mostly-used threshold"
                        );
                        assert_eq!(route.test_abandoned_count(), Some(0));
                        index += 1;
                    }

                    route = match unsafe { route.remote_free_after_thread_exit(blocks[index]) } {
                        Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::StillLive(route)) => {
                            route
                        }
                        Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::Released) => {
                            panic!("the first below-mostly-used free cannot release the full large page")
                        }
                        Err(_) => panic!("the first below-mostly-used free reabandons the page to mapped"),
                    };
                    assert!(
                        route.test_is_mapped(),
                        "the source reabandons the page into the static-main bitmap below mostly used"
                    );
                    assert_eq!(route.test_abandoned_count(), Some(1));
                    index += 1;

                    while index + 1 < capacity {
                        route = match unsafe { route.remote_free_after_thread_exit(blocks[index]) } {
                            Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::StillLive(route)) => {
                                route
                            }
                            Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::Released) => {
                                panic!("a nonfinal mapped client free cannot release the large page")
                            }
                            Err(_) => panic!("a mapped large client free remains in the route"),
                        };
                        assert!(route.test_is_mapped());
                        index += 1;
                    }

                    match unsafe { route.remote_free_after_thread_exit(blocks[index]) } {
                        Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::Released) => {}
                        Ok(MainHeapThreadProcessPageExitFullLargeFreeResult::StillLive(route)) => {
                            core::mem::forget(route);
                            panic!("the final client free releases the full-large route")
                        }
                        Err(_) => panic!("the final client free releases the full-large route"),
                    }
                    for offset in 0..slice_count {
                        let address = unsafe { slice_start.add(offset * crate::config::ARENA_SLICE_SIZE) };
                        assert!(
                            unsafe { page_map.page_map().unwrap().checked_lookup(address) }.is_null(),
                            "the final route leaves every complete-large arena address PageMap-null"
                        );
                    }
                    assert_eq!(
                        unsafe { arena.pages() }.unwrap().is_clear_range(slice, 1),
                        Some(true),
                        "the final route release clears the ordinary main-arena bit"
                    );
                    assert_eq!(
                        page_map.begin_page_lifecycle().unwrap().finish(),
                        Ok(()),
                        "the completed full-large route reopens an empty process map"
                    );
                });
                worker
                    .join()
                    .expect("the full-large process route remains local to its later owner");
            });
            core::mem::forget(main);
        })
        .join()
        .expect("full-large post-exit route fixture remains current-thread local");
    }

